      clientId: args.clientId,
      authorId: userId,
      kind,
      body,
      isReply: false,
      likeCount: 0,
      repostCount: 0,
      replyCount: 0,
      createdAt: now,
    });
    if (kind === 'images') {
      let ord = 0;
      for (const raw of images) {
        const image = await ctx.assets.attach(raw, { upload: 'publicImageUpload' });
        await ctx.db.insert('postMedia', { postId, kind: 'image', ord, image });
        ord += 1;
      }
